insert into public.must_knows (id, route_id, category, custom_label, chips, note, sort) values ('bc5ff807-ef1e-5fab-8590-87621e79998d', '5eed0001-0000-4000-a000-000000000001', 'visa', null, '{"e-Visa"}', '90 days. Apply online about a week before.', 0);
insert into public.must_knows (id, route_id, category, custom_label, chips, note, sort) values ('adf20bed-eab4-50d3-8612-ab45d0900d17', '5eed0001-0000-4000-a000-000000000001', 'permits', null, '{"Buy on the spot"}', 'Ha Giang permit, about 250k VND. Your homestay sorts it.', 1);
insert into public.must_knows (id, route_id, category, custom_label, chips, note, sort) values ('bb1102d0-7ccf-5d90-925b-a994a967b6e7', '5eed0001-0000-4000-a000-000000000001', 'wheels', null, '{"IDP","Local licence"}', 'Police checkpoints on the loop. No licence? Hire an easy rider.', 2);
insert into public.must_knows (id, route_id, category, custom_label, chips, note, sort) values ('3d1790d6-f31c-5400-ae6c-4ccb7b6bf066', '5eed0001-0000-4000-a000-000000000001', 'cash', null, '{"Mostly cash"}', 'ATMs in Ha Giang and Dong Van only.', 3);
insert into public.must_knows (id, route_id, category, custom_label, chips, note, sort) values ('5d888408-b643-54f0-a80e-be18bfc4f93d', '5eed0001-0000-4000-a000-000000000001', 'sim', null, '{"Patchy"}', 'Viettel has the best signal up north. Patchy on the passes.', 4);
insert into public.must_knows (id, route_id, category, custom_label, chips, note, sort) values ('9c1ff500-8032-56f9-b704-b6b323ab6e3e', '5eed0001-0000-4000-a000-000000000001', 'book', null, '{"Weekends only"}', 'Walk-ins fine Monday to Thursday.', 5);
insert into public.must_knows (id, route_id, category, custom_label, chips, note, sort) values ('35ece8cc-a4f4-57ad-8807-5a4a69cd701c', '5eed0001-0000-4000-a000-000000000001', 'roads', null, '{"Mixed"}', 'Smooth main loop, rough near Du Gia.', 6);
insert into public.must_knows (id, route_id, category, custom_label, chips, note, sort) values ('10767b81-fff8-5088-a625-4a4a475a7926', '5eed0001-0000-4000-a000-000000000001', 'water', null, '{"Bottled only"}', 'Clinic in Dong Van, hospital in Ha Giang.', 7);
insert into public.must_knows (id, route_id, category, custom_label, chips, note, sort) values ('eec4f1ce-c204-58d1-9f1e-40fb533f9256', '5eed0001-0000-4000-a000-000000000001', 'scams', null, '{"Watch out"}', 'Fake fines at a few checkpoints. Ask for a written receipt.', 8);
insert into public.must_knows (id, route_id, category, custom_label, chips, note, sort) values ('804793a8-d8a6-542e-a7fa-c417abafd73f', '5eed0001-0000-4000-a000-000000000001', 'dress', null, '{"Cover up at sacred places"}', 'Ask before taking photos at Hmong markets.', 9);
insert into public.must_knows (id, route_id, category, custom_label, chips, note, sort) values ('08947448-c6a4-538d-8098-67fa0d2ab239', '5eed0001-0000-4000-a000-000000000001', 'wildlife', null, '{"Stray dogs"}', 'Village dogs bark a lot. Give them space and they lose interest.', 10);
insert into public.must_knows (id, route_id, category, custom_label, chips, note, sort) values ('7e5149a4-682f-5da0-946b-354571a9aa88', '5eed0001-0000-4000-a000-000000000001', 'pack', null, '{"Waterproof layer","Warm layer","Bring snacks"}', 'Nights drop to 8°. Snacks for the passes.', 11);
insert into public.must_knows (id, route_id, category, custom_label, chips, note, sort) values ('62e65065-a489-51e3-a690-084964fbb216', '5eed0001-0000-4000-a000-000000000001', 'custom', 'Tet holiday', '{"Avoid Tet week"}', 'Most homestays shut for about 5 days.', 12);
